	for promise in PromiseRegistry.get_all():
		if promise.status == "open" and promise.due_sprint >= 0:
			var key: String = promise.customer_id + "|" + promise.feature_id
			promised[key] = mini(int(promised.get(key, promise.due_sprint)), promise.due_sprint)
	var keyed: Array = []
	for r in GameState.product.get("requests", []):
		var customer: String = SprintCatalog.customer_name(r)
		if r.status not in ["open", "met"] or customer == "":
			continue
		var card_id: String = "feat:" + r.step if stored.has("feat:" + r.step) else String(r.card_id)
		var area_id: String = SprintCatalog.area_of_line(r.line)
		var promise: int = promised.get(String(r.customer_id) + "|" + String(r.step), -1)
		var due: int = promise if promise >= 0 else int(r.due_sprint)
		var when: Dictionary = _due(due)
		var card_name: String = SprintCatalog.step_name(r.step)
		var parts: PackedStringArray = [customer,
			_t("PRODUCT_TIP_CARD_MODULE").format({"card": card_name, "module": SprintCatalog.area_name(area_id)}),
			_t("PRODUCT_PER_YEAR").format({"amount": Fmt.money_exact(int(r.value))})]
		if promise >= 0:
			parts.append(_t("PRODUCT_TIP_PROMISE").format({"when": when.text}))
		var state := "met" if r.status == "met" else ("" if not tags.has(card_id) else (
			"this" if tags[card_id] == SprintSystem.sprint_number() else "next"))
		keyed.append([[int(state == "met"), int(state != ""), int(not when.soon), due, keyed.size()], {"customer": customer,
			"card_id": card_id, "card_name": card_name, "module_id": area_id, "mono": _mono(area_id), "value": int(r.value),
			"due_text": when.text, "soon": when.soon, "state": state, "state_text": _state_text(state, run.get("cards", {}).get(card_id, {})),
			"planned": state in ["this", "next"], "tip": SprintUiShared.SEP.join(parts)}])
	keyed.sort_custom(func(a: Array, b: Array) -> bool: return a[0] < b[0])
	return keyed.map(func(k: Array) -> Dictionary: return k[1])


## Planda olan talebin kartının durumu: sonraki sütundaysa "Sonraki sprint", koşan sprintte (`card` zaman ekseninin kaydı) şimdiki
## anda koşan aşama ve yüzdesi ("Test %40": yüzde aşamanın hazırlıkla birlikte yapılan işinin payı); kart o an hiçbir aşamada
## koşmuyorsa ya da sprint koşmuyorsa "" (satırda yalnız tarih kalır).
static func _state_text(state: String, card: Dictionary) -> String:
	if state == "next":
		return _t("PRODUCT_REQUEST_NEXT_SPRINT")
	if state != "this" or SprintSystem.mode() != "active":
		return ""
	var now: float = now_at("active")
	for s: Dictionary in card.get("stages", []):
		if s.start - SprintSystem.EPS <= now and now < s.end - SprintSystem.EPS:
			var pct: int = floori(clampf((s.pre + SprintTimeline.done_at(s, now)) / (s.pre + s.need), 0.0, 1.0) * 100.0)
			return _t("PRODUCT_STAGE_PCT").format({"stage": SprintUiShared.stage_name(s.stage), "pct": Fmt.percent(pct, 0)})

